<template><AppShell><PageHeader eyebrow="Course operations" title="강의 관리" description="강의를 등록·수정하고 활성 상태와 차시 구성을 관리합니다."><router-link class="button accent" to="/admin/courses/new"><Plus :size="16"/> 새 강의 등록</router-link></PageHeader><section class="metric-grid summary"><article v-for="item in stats" :key="item.label" class="metric card"><div class="metric-head"><span>{{ item.label }}</span><span class="metric-icon"><component :is="item.icon" :size="17"/></span></div><div><strong class="metric-value">{{ item.value }}</strong><p class="trend">{{ item.desc }}</p></div></article></section><section class="panel course-panel"><div class="table-toolbar"><div class="table-search"><Search :size="16"/><input placeholder="강의명 검색"/></div><select class="select"><option>모든 언어</option><option>영어</option><option>일본어</option></select><select class="select"><option>모든 상태</option><option>ACTIVE</option><option>INACTIVE</option></select><button class="button small"><SlidersHorizontal :size="14"/> 필터</button></div><div class="course-admin-list"><article v-for="(course,i) in courses" :key="course.id"><div class="course-image" :class="`tone-${course.tone}`"><img :src="course.image" :alt="course.title"/></div><div class="course-info"><div><span class="tag" :class="i===4?'gray':''">{{ i===4?'INACTIVE':'ACTIVE' }}</span><span>{{ course.language }} · {{ course.level }} · {{ course.situation }}</span></div><h2>{{ course.title }}</h2><p>COURSE-{{ course.id }} · {{ course.duration }} · {{ course.students }}명 수강</p></div><div class="lesson-count"><BookOpen :size="16"/><span><strong>{{ 10+i }}</strong>차시</span></div><div class="course-actions"><router-link class="button small" :to="`/admin/courses/${course.id}/edit`"><Pencil :size="14"/> 수정</router-link><button class="button small" @click="toggle(i)"><Power :size="14"/> {{ active[i]?'비활성화':'활성화' }}</button><button class="row-menu"><MoreHorizontal :size="17"/></button></div></article></div></section></AppShell></template>
<script setup>import { reactive } from 'vue'; import { Plus,LibraryBig,BadgeCheck,BookX,UsersRound,Search,SlidersHorizontal,BookOpen,Pencil,Power,MoreHorizontal } from '@lucide/vue'; import AppShell from '@/components/AppShell.vue'; import PageHeader from '@/components/PageHeader.vue'; import { courses } from '@/data/mockData.js'; const stats=[{label:'전체 강의',value:'48',desc:'이번 달 +6',icon:LibraryBig},{label:'활성 강의',value:'45',desc:'노출률 93.8%',icon:BadgeCheck},{label:'비활성 강의',value:'3',desc:'상태 확인 필요',icon:BookX},{label:'전체 수강',value:'7,340',desc:'강의당 평균 153명',icon:UsersRound}]; const active=reactive(courses.map((_,i)=>i!==4)); function toggle(i){active[i]=!active[i]}</script>
<style scoped>.summary{margin-bottom:14px}.course-panel{padding:0;overflow:hidden}.table-toolbar{display:flex;gap:8px;padding:13px 16px;border-bottom:1px solid var(--line)}.table-search{width:270px;height:38px;display:flex;align-items:center;gap:8px;padding:0 10px;background:var(--surface-2);border-radius:9px;color:var(--muted)}.table-search input{background:transparent;border:0;outline:0;font-size:10px}.table-toolbar .select{width:130px;min-height:38px;font-size:9px}.table-toolbar .button{margin-left:auto}.course-admin-list article{display:grid;grid-template-columns:120px 1fr 90px auto;align-items:center;gap:18px;padding:14px 16px;border-bottom:1px solid var(--line)}.course-admin-list article:last-child{border-bottom:0}.course-image{height:74px;display:grid;place-items:center;overflow:hidden;background:#dce9df;border-radius:10px}.course-image img{width:85%;height:85%;object-fit:contain;mix-blend-mode:multiply}.tone-blue{background:#dce7f3}.tone-amber{background:#f4e8d0}.tone-purple{background:#e8e1f0}.tone-red{background:#f1ddd8}.course-info>div{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:8px}.course-info h2{margin:7px 0 3px;font-size:13px}.course-info p{color:var(--muted);font-size:8px}.lesson-count{display:flex;align-items:center;gap:8px;color:var(--muted)}.lesson-count strong,.lesson-count span{display:block}.lesson-count strong{color:var(--ink);font-size:12px}.lesson-count span{font-size:8px}.course-actions{display:flex;gap:6px}.row-menu{color:var(--muted);background:transparent}@media(max-width:900px){.course-admin-list article{grid-template-columns:90px 1fr auto}.lesson-count{display:none}.course-actions .button{font-size:0}.course-actions .button svg{margin:0}}@media(max-width:620px){.table-toolbar{flex-wrap:wrap}.table-search{width:100%}.table-toolbar .button{margin-left:0}.course-admin-list article{grid-template-columns:72px 1fr}.course-actions{grid-column:2}.course-image{height:60px}}</style>
